const ambientes = [
  { name: 'Dev', url: 'https://portalpaciente-dev.bupa.cl/login' },
  { name: 'QA', url: 'https://portalpaciente-qa.bupa.cl/login' },
  { name: 'Staging', url: 'https://portalpaciente-staging.bupa.cl/login' },
  { name: 'Prod', url: 'https://portalpaciente.bupa.cl/login' }
];

const results = [];
for (const amb of ambientes) {
  try {
    const resp = await this.helpers.httpRequest({
      method: 'GET',
      url: amb.url,
      returnFullResponse: true,
      timeout: 15000,
      ignoreHttpStatusErrors: true
    });
    const code = resp.statusCode || resp.status || 0;
    results.push({ name: amb.name, url: amb.url, statusCode: code, isUp: code >= 200 && code < 400 });
  } catch (e) {
    results.push({ name: amb.name, url: amb.url, statusCode: 0, isUp: false, error: e.message });
  }
}

return [{ json: { results } }];

